"""python -m analyses.stockpiling.run [db] -> result_stockpiling table and report.md"""
import sys
from pathlib import Path

import sqlite_utils

from .model import swings

HERE = Path(__file__).parent
EVENT_YEAR = 2025


def pct(x: float) -> str:
    return f"{x * 100:+.1f}%"


def render(rows: list[dict]) -> str:
    event = next(r for r in rows if r["is_event"])
    placebos = [r for r in rows if not r["is_event"] and not r["after_event"]]
    lines = [
        "# Stockpiling before the 1 January 2025 tax rise", "",
        "Generated by `python -m analyses.stockpiling.run`. See question.md for the method and its limits.", "",
        "| Winter | December yoy | January yoy | Swing (Dec - Jan) | Dec + Jan yoy | |",
        "|---|---|---|---|---|---|",
    ]
    for r in rows:
        tag = "tax rise" if r["is_event"] else "base effect of the stockpile" if r["after_event"] else "placebo"
        lines.append(f"| Dec {r['year'] - 1} / Jan {r['year']} | {pct(r['pre_yoy'])} | {pct(r['post_yoy'])} "
                     f"| {r['swing'] * 100:+.1f} pp | {pct(r['net_yoy'])} | {tag} |")
    lines += ["", "## Reading", "",
              f"- Winter 2024/25: December {pct(event['pre_yoy'])}, January {pct(event['post_yoy'])}, "
              f"a swing of {event['swing'] * 100:.1f} points. The two months together changed by {pct(event['net_yoy'])}.",
              f"- Placebo winters ({len(placebos)}): swings of "
              + ", ".join(f"{r['swing'] * 100:+.1f}" for r in placebos) + " points.",
              f"- Placebo swings are all negative (January stronger than December); the tax winter is the only positive one. "
              f"But single-month growth is noisy: placebo swings span {min(r['swing'] for r in placebos) * 100:.1f} to "
              f"{max(r['swing'] for r in placebos) * 100:.1f} points, so the event stands out in sign and size, not by a wide margin.",
              f"- Dec + Jan together: {pct(event['net_yoy'])} in the tax winter against "
              + ", ".join(pct(r['net_yoy']) for r in placebos) + " in the placebos, so the pull-forward looks like timing, not lost volume.",
              "- Not controlled: working days and the number of weekends in each month, which can move a single month by several points.",
              "- Three placebos and one event is a small sample; this shows the pattern, it does not estimate an effect size.", ""]
    return "\n".join(lines)


if __name__ == "__main__":
    db = sqlite_utils.Database(sys.argv[1] if len(sys.argv) > 1 else "tobacco.db")
    packs = {(r["year"], r["month"]): r["packs"] for r in db.query((HERE / "data.sql").read_text())}
    rows = swings(packs, pre_month=12, post_month=1, event_year=EVENT_YEAR)
    db["result_stockpiling"].insert_all(rows, pk="year", replace=True)
    (HERE / "report.md").write_text(render(rows), encoding="utf-8")
    print((HERE / "report.md").read_text())
